B.aJ1=A.a(s(["Adrenalina \u2014 0,05\u20130,5 \xb5g/kg/min IV (inotr\xf3pico + vasopressor alternativo; mais arritmog\xeanica)","Vasopressina \u2014 0,03\u20130,04 UI/min IV (adjuvante \xe0 noradrenalina em choque refrat\xe1rio)","Milrinona \u2014 0,25\u20130,75 \xb5g/kg/min IV (inotr\xf3pico sem taquicardia; cuidado com hipotens\xe3o)","Furosemida \u2014 40\u201380 mg IV (descongest\xe3o ap\xf3s PA estabilizada)","Levosimendan \u2014 0,1\u20130,2 \xb5g/kg/min (inotr\xf3pico sensibilizador de c\xe1lcio; uso em ICC cr\xf4nica descompensada)"]),t.s)
B.aGw=A.a(s(["Adrenalina \u2014 0,05\u20130,5 \xb5g/kg/min IV (inotr\xf3pico + vasopresor alternativo; m\xe1s arritmog\xe9nica)","Vasopresina \u2014 0,03\u20130,04 UI/min IV (adyuvante a noradrenalina en choque refractario)","Milrinona \u2014 0,25\u20130,75 \xb5g/kg/min IV (inotr\xf3pico sin taquicardia; cuidado con hipotensi\xf3n)","Furosemida \u2014 40\u201380 mg IV (descongesti\xf3n tras estabilizaci\xf3n de PA)","Levosimend\xe1n \u2014 0,1\u20130,2 \xb5g/kg/min (inotr\xf3pico sensibilizador de calcio; uso en ICC cr\xf3nica descompensada)"]),t.s)
