B.dbJ=new A.aF("tromboembolismo_pulmonar",B.bMp,B.bOz,B.c8,B.bQB,B.coq,B.bqh,B.crT,B.czp,B.d1n,B.cHi,B.bXk,B.cKf,B.ccZ,B.d3A,B.cdi,B.cCn,B.cQP,B.c9l,B.c1_,B.cRa,B.ckp)
