B.aTt=A.a(s(["PAM \u226565 mmHg (\u226570\u201375 em idosos e hipertensos cr\xf4nicos)","Lactato <2 mmol/L em 6h; clearance \u226510% nas primeiras 2h","Diurese \u22650,5 mL/kg/h ap\xf3s ressuscita\xe7\xe3o","ATB em <1h ap\xf3s reconhecimento da sepse","Controle do foco infeccioso em <6\u201312h quando poss\xedvel","SpO2 \u226592%; PaO2/FiO2 >200 em ventilado","Glicemia 140\u2013180 mg/dL"]),t.s)
B.aZB=A.a(s(["PAM \u226565 mmHg","Lactato <2 mmol/L en 6 h","Diuresis \u22650,5 mL/kg/h tras resucitaci\xf3n","ATB en <1 h tras reconocimiento de sepsis","Control del foco infeccioso en <6\u201312 h","Glucemia 140\u2013180 mg/dL"]),t.s)
B.cJK=new A.b(B.a,[B.aTt,B.aZB],t.M)
B.b0b=A.a(s(["Noradrenalina \u2014 0,1\u20131 \xb5g/kg/min IV (vasopressor de 1\xaa linha; PAM alvo \u226565 mmHg; NUNCA adrenalina/dopamina como 1\xaa escolha no choque s\xe9ptico)","Meropenem \u2014 1\u20132 g 8/8h IV (cobertura ampla Gram-negativo, pseudomonas, ESBL; 1\xaa linha em sepse grave)","Pip-Tazo (piperacilina-tazobactam) \u2014 4,5 g 6/6h IV (cobertura ampla menos ESBL; associar vancomicina se MRSA)","Vancomicina \u2014 15\u201320 mg/kg 8/8h IV (cobertura MRSA, Enterococcus; monitorar n\xedvel s\xe9rico/AUC)"]),t.s)
B.aVn=A.a(s(["Noradrenalina \u2014 0,1\u20131 \xb5g/kg/min IV (vasopresor 1\xaa l\xednea)","Meropenem \u2014 1\u20132 g c/8 h IV (cobertura amplia Gram-negativo)","Pip-Tazo \u2014 4,5 g c/6 h IV (cobertura amplia sin ESBL)","Vancomicina \u2014 15\u201320 mg/kg c/8 h IV (MRSA, Enterococcus)"]),t.s)
