B.bvu=A.a(s(["K+ <6,0 mEq/L en 2 h; K+ <5,5 mEq/L antes del alta","ECG normalizado (QRS <120 ms)","Ausencia de arritmias card\xedacas","Causa identificada y corregida","Glucemia >70 mg/dL durante y despu\xe9s de insulina"]),t.s)
B.cKS=new A.b(B.a,[B.bh4,B.bvu],t.M)
B.aWH=A.a(s(["Gluconato de c\xe1lcio 10% \u2014 10 mL (1 g) IV em 2\u20133 min; estabiliza\xe7\xe3o de membrana; N\xc3O reduz K+ s\xe9rico; dura\xe7\xe3o 30\u201360 min; repetir se ECG n\xe3o melhora em 5 min","Insulina Regular \u2014 10 UI IV + Glicose 50% 50 mL; shift K+ de 0,6\u20131 mEq/L; onset 15\u201330 min; dura\xe7\xe3o 4\u20136h; monitorar glicemia","Salbutamol nebuliza\xe7\xe3o \u2014 10\u201320 mg; shift K+ 0,5\u20131 mEq/L adicional; in\xedcio 30 min; seguro para combinar com insulina","Bicarbonato de s\xf3dio \u2014 50\u2013100 mEq IV; APENAS se pH <7,2; efeito limitado isolado em hiperpotassemia sem acidose"]),t.s)
B.bsA=A.a(s(["Gluconato de calcio 10% \u2014 10 mL IV en 2\u20133 min; estabilizaci\xf3n de membrana; NO reduce K+ s\xe9rico","Insulina Regular \u2014 10 UI IV + Glucosa 50% 50 mL; shift K+ 0,6\u20131 mEq/L","Salbutamol nebulizaci\xf3n \u2014 10\u201320 mg; shift K+ 0,5\u20131 mEq/L adicional","Bicarbonato de sodio \u2014 SOLO si pH <7,2"]),t.s)
