B.brB=A.a(s(["BISAP \u22653: BUN >25, altera\xe7\xe3o de consci\xeancia, SIRS, idade >60, derrame pleural \u2192 UTI","PCR >150 mg/L em 48h: marcador mais pr\xe1tico de PAG","Hemat\xf3crito >44% na admiss\xe3o: marcador de hemoconcentra\xe7\xe3o e necrose","Ranson \u22653: mortalidade >15%","TC: necrose pancre\xe1tica \u226530% (Balthazar D-E) ou cole\xe7\xe3o peripancre\xe1tica","Fal\xeancia org\xe2nica: PaO2/FiO2 <300, creatinina >1,9, PAM <70 com vasopressor"]),t.s)
B.aUf=A.a(s(["BISAP \u22653: BUN >25, alteraci\xf3n consciencia, SIRS, edad >60, derrame pleural \u2192 UCI","PCR >150 mg/L en 48 h: marcador pr\xe1ctico de PAG","Hematocrito >44% en la admisi\xf3n: hemoconcentraci\xf3n y necrosis","Ranson \u22653: mortalidad >15%","TC: necrosis pancre\xe1tica \u226530% (Balthazar D-E)","Falla org\xe1nica: PaO2/FiO2 <300, creatinina >1,9"]),t.s)
