B.b3l=A.a(s(["Via a\xe9rea patente + SpO2 \u226595% em 5 min","PAS >90 mmHg (ou PAM >65) com m\xednimo de fluidos (hipotens\xe3o permissiva se hemorragia incontrolada)","Controle de hemorragia externa: hemostasia em <2 min por compress\xe3o direta","GCS est\xe1vel ou melhorando ap\xf3s estabiliza\xe7\xe3o","Temperatura corporal \u226536\xb0C (prevenir tr\xedade da morte)","Decis\xe3o cir\xfargica em <60 min se FAST+ + instabilidade"]),t.s)
B.bxi=A.a(s(["V\xeda a\xe9rea permeable + SpO2 \u226595% en 5 min","PAS >90 mmHg (hipotensi\xf3n permisiva si hemorragia incontrolable)","Control hemorragia externa: hemostasia en <2 min por compresi\xf3n","GCS estable o mejorando tras estabilizaci\xf3n","Temperatura corporal \u226536\xb0C (prevenir tr\xedada de la muerte)","Decisi\xf3n quir\xfargica en <60 min si FAST+ + inestabilidad"]),t.s)
B.cvy=new A.b(B.a,[B.b3l,B.bxi],t.M)
B.bsS=A.a(s(['Ringer Lactato \u2014 1L IV r\xe1pido no "C" do ATLS; evitar SF 0,9% (acidose hiperclor\xeamica); alvo PAM 65 (ou 50\u201365 permissiva)',"Concentrado de Hem\xe1cias \u2014 transfus\xe3o se Hb <8 g/dL ou choque hemorr\xe1gico; raz\xe3o 1:1:1 com PFC e plaquetas","\xc1cido Tranex\xe2mico \u2014 1g IV em 10 min (dose ataque) + 1g IV em 8h (manuten\xe7\xe3o); janela: <3h do trauma","Ketamina \u2014 1\u20132 mg/kg IV: indu\xe7\xe3o para IOT em trauma com hipotens\xe3o (preserva PA; broncodilatador)"]),t.s)
